def component_grids(grid, conn=8):
 h,w=len(grid),len(grid[0]); seen=set(); arr=[]
 dirs=[(dy,dx) for dy in (-1,0,1) for dx in (-1,0,1) if (dy,dx)!=(0,0)] if conn==8 else [(1,0),(-1,0),(0,1),(0,-1)]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    stack=[(r,c)];seen.add((r,c)); cells=[]
    while stack:
     y,x=stack.pop();cells.append((y,x))
     for dy,dx in dirs:
      ny,nx=y+dy,x+dx
      if 0<=ny<h and 0<=nx<w and grid[ny][nx] and (ny,nx) not in seen:
       seen.add((ny,nx));stack.append((ny,nx))
    r0=min(y for y,x in cells);r1=max(y for y,x in cells);c0=min(x for y,x in cells);c1=max(x for y,x in cells)
    crop=[[grid[y][x] if (y,x) in set(cells) else 0 for x in range(c0,c1+1)] for y in range(r0,r1+1)]
    arr.append((len(cells),crop,(r0,c0)))
 return arr
