def symmetries(g):
 h=len(g);w=len(g[0]);
 return {'h':g==[row[::-1] for row in g], 'v':g==g[::-1], '180':g==[row[::-1] for row in g[::-1]], 'transpose':h==w and all(g[r][c]==g[c][r] for r in range(h) for c in range(w))}
def stats(grid):
 stats=[]
 for n,g,loc in component_grids(grid,8):
  h,w=len(g),len(g[0]); pix=sum(map(sum,g))
  per=sum(1 for r in range(h) for c in range(w) if g[r][c] for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)] if not(0<=r+dy<h and 0<=c+dx<w and g[r+dy][c+dx]))
  # 4-components
  nc=len(component_grids(g,4))
  stats.append((loc,n,h,w,pix,h*w,round(pix/(h*w),3),per,nc,symmetries(g)))
 return stats
